CM = 2.54  # the API works in centimetres
COMPONENTS = ['Shell', 'Glazing', 'Floors', 'Kitchen', 'Baths', 'Living', 'Storage']
IS_ZERO = ('0', '0 in')


def set_params(design):
    ups = design.userParameters
    for name, expr, comment in PARAMS:
        p = ups.itemByName(name)
        if p:
            p.expression = expr
            p.comment = comment
        else:
            ups.add(name, adsk.core.ValueInput.createByString(expr), 'in', comment)


def dim(sk, pt, axis, expr):
    g = pt.geometry
    if axis == 'x':
        orient = adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation
        tp = adsk.core.Point3D.create(g.x / 2, g.y + 4, 0)
    else:
        orient = adsk.fusion.DimensionOrientations.VerticalDimensionOrientation
        tp = adsk.core.Point3D.create(g.x + 4, g.y / 2, 0)
    d = sk.sketchDimensions.addDistanceDimension(sk.originPoint, pt, orient, tp)
    d.parameter.expression = expr


def nearest(points, x, y):
    return min(points, key=lambda p: (p.geometry.x - x) ** 2 + (p.geometry.y - y) ** 2)


def ground(comp):
    # the floor is the XZ plane in a Y-up design, XY in a Z-up one; either way
    # sketch y runs north and extrusions go up
    prefs = adsk.core.Application.get().preferences.generalPreferences
    if prefs.defaultModelingOrientation == adsk.core.DefaultModelingOrientations.YUpModelingOrientation:
        return comp.xZConstructionPlane
    return comp.xYConstructionPlane


def sketch(comp, s):
    sk = comp.sketches.add(ground(comp))
    sk.name = s['id']
    sk.isComputeDeferred = True
    if s['shape'] == 'rect':
        (x0, x1), (y0, y1) = s['xv'], s['yv']
        p0 = adsk.core.Point3D.create(x0 * CM, -y0 * CM, 0)
        p1 = adsk.core.Point3D.create(x1 * CM, -y1 * CM, 0)
        lines = sk.sketchCurves.sketchLines.addTwoPointRectangle(p0, p1)
        pts = []
        for i in range(lines.count):
            pts += [lines.item(i).startSketchPoint, lines.item(i).endSketchPoint]
        a, b = nearest(pts, p0.x, p0.y), nearest(pts, p1.x, p1.y)
        dim(sk, a, 'x', s['x'][0])
        dim(sk, a, 'y', s['y'][0])
        dim(sk, b, 'x', s['x'][1])
        dim(sk, b, 'y', s['y'][1])
    else:
        c = sk.sketchCurves.sketchCircles.addByCenterRadius(
            adsk.core.Point3D.create(s['cxv'] * CM, -s['cyv'] * CM, 0), s['rv'] * CM)
        dim(sk, c.centerSketchPoint, 'x', s['cx'])
        dim(sk, c.centerSketchPoint, 'y', s['cy'])
        d = sk.sketchDimensions.addDiameterDimension(
            c, adsk.core.Point3D.create(s['cxv'] * CM + 3, -s['cyv'] * CM + 3, 0))
        d.parameter.expression = '2 * ({})'.format(s['r'])
    sk.isComputeDeferred = False
    return sk


def extrude(comp, sk, s, op, bodies=None):
    ext = comp.features.extrudeFeatures
    inp = ext.createInput(sk.profiles.item(0), op)
    bot, top = s['z']
    if bot.strip() not in IS_ZERO:
        inp.startExtent = adsk.fusion.OffsetStartDefinition.create(adsk.core.ValueInput.createByString(bot))
    dist = adsk.core.ValueInput.createByString('({}) - ({})'.format(top, bot))
    inp.setOneSideExtent(adsk.fusion.DistanceExtentDefinition.create(dist),
                         adsk.fusion.ExtentDirections.PositiveExtentDirection)
    if bodies:
        inp.participantBodies = bodies
    f = ext.add(inp)
    f.name = s['id']
    return f


def combine(comp, bodies, name):
    target = bodies[0]
    if len(bodies) > 1:
        tools = adsk.core.ObjectCollection.create()
        for b in bodies[1:]:
            tools.add(b)
        ci = comp.features.combineFeatures.createInput(target, tools)
        ci.operation = adsk.fusion.FeatureOperations.JoinFeatureOperation
        comp.features.combineFeatures.add(ci)
    target.name = name
    return target


def finish(design, key):
    spec = FINISHES['appearances'][key]
    name = '4479 ' + key
    a = design.appearances.itemByName(name)
    if a:
        return a
    lib = adsk.core.Application.get().materialLibraries.itemByName('Fusion Appearance Library')
    a = design.appearances.addByCopy(lib.appearances.itemByName(spec['from']), name)
    if 'color' in spec:
        r, g, b = spec['color']
        for i in range(a.appearanceProperties.count):
            p = adsk.core.ColorProperty.cast(a.appearanceProperties.item(i))
            if p and not p.isReadOnly:
                p.value = adsk.core.Color.create(r, g, b, 255)
                break
    return a


def apply_finishes(design, comps):
    kinds = {s['id']: s.get('kind') for s in SOLIDS}
    assign = FINISHES['assign']
    for comp in comps.values():
        for i in range(comp.bRepBodies.count):
            body = comp.bRepBodies.item(i)
            n = body.name
            key = assign.get(n) or assign.get(kinds.get(n) or '') or ('glass' if comp.name == 'Glazing' else None)
            if comp.name == 'Glazing':
                key = assign.get(n) or assign['glass']
            if key:
                body.appearance = finish(design, key)


def cut_view(design):
    """A section at cutH that slices off everything above it, plus a named view.
    Both live in the root component, so rebuilding the generated components
    keeps them. Toggle the cut with the eye on Analysis > Wall cut."""
    app = adsk.core.Application.get()
    root = design.rootComponent
    planes = root.constructionPlanes
    plane = next((planes.item(i) for i in range(planes.count) if planes.item(i).name == 'Cut plane'), None)
    if not plane:
        inp = planes.createInput()
        inp.setByOffset(ground(root), adsk.core.ValueInput.createByString('cutH'))
        plane = planes.add(inp)
        plane.name = 'Cut plane'
        plane.isLightBulbOn = False
    sections = design.analyses.sectionAnalyses
    if 'Wall cut' not in [sections.item(i).name for i in range(sections.count)]:
        inp = sections.createInput(plane, 0)
        inp.isHatchShown = False
        inp.sectionColor = adsk.core.Color.create(64, 64, 64, 255)
        sec = sections.add(inp)
        sec.name = 'Wall cut'
    vp = app.activeViewport
    cam = vp.camera
    cam.viewOrientation = adsk.core.ViewOrientations.IsoTopRightViewOrientation
    cam.isFitView = True
    vp.camera = cam
    vp.fit()
    if 'Cut iso' not in [design.namedViews.item(i).name for i in range(design.namedViews.count)]:
        design.namedViews.add(vp.camera, 'Cut iso')


def run(_context):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    design.designType = adsk.fusion.DesignTypes.ParametricDesignType
    design.fusionUnitsManager.distanceDisplayUnits = adsk.fusion.DistanceUnits.InchDistanceUnits
    root = design.rootComponent

    set_params(design)

    # rebuild the generated components from scratch
    for i in range(root.occurrences.count - 1, -1, -1):
        occ = root.occurrences.item(i)
        if occ.component.name in COMPONENTS:
            occ.deleteMe()
    comps = {}
    for name in COMPONENTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        occ.component.name = name
        comps[name] = occ.component

    NEW = adsk.fusion.FeatureOperations.NewBodyFeatureOperation
    CUT = adsk.fusion.FeatureOperations.CutFeatureOperation
    groups = {}

    # solids that make new bodies, grouped into one body per group
    for s in SOLIDS:
        if s['op'] != 'new':
            continue
        comp = comps[s['comp']]
        f = extrude(comp, sketch(comp, s), s, NEW)
        body = f.bodies.item(0)
        key = (s['comp'], s.get('group') or s['id'])
        groups.setdefault(key, {'bodies': [], 'name': s.get('group') or s['id']})
        groups[key]['bodies'].append(body)

    named = {}
    for (comp_name, group), g in groups.items():
        named[(comp_name, group)] = combine(comps[comp_name], g['bodies'], g['name'])

    # openings cut through the walls
    walls = named[('Shell', 'Walls')]
    for s in SOLIDS:
        if s['op'] == 'cut':
            comp = comps[s['comp']]
            extrude(comp, sketch(comp, s), s, CUT, [walls])

    apply_finishes(design, comps)

    # sketches only clutter the model view
    for comp in comps.values():
        for i in range(comp.sketches.count):
            comp.sketches.item(i).isLightBulbOn = False
    cut_view(design)

    bad = []
    for i in range(design.timeline.count):
        item = design.timeline.item(i)
        if item.healthState != adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState:
            bad.append('{}: {}'.format(item.name, item.errorOrWarningMessage))
    print('{}: {} parameters, {} solids, {} bodies'.format(
        PLAN, len(PARAMS), len(SOLIDS), sum(c.bRepBodies.count for c in comps.values())))
    print('timeline problems: {}'.format(bad if bad else 'none'))
